import React, { useState, useEffect } from 'react';
import axiosInstance from 'axios';

export default function TeacherQuiz({ userName, subject, qualifications }) {
  const [quizzes, setQuizzes] = useState([]);
  const [questionBank, setQuestionBank] = useState([]);
  const [selectedQuizId, setSelectedQuizId] = useState('');
  
  // Quiz Registration
  const [quizTitle, setQuizTitle] = useState('');
  
  // Question Form
  const [editingId, setEditingId] = useState(null); // Edit කරනවාද නැද්ද කියා බැලීමට
  const [qText, setQText] = useState('');
  const [optA, setOptA] = useState('');
  const [optB, setOptB] = useState('');
  const [optC, setOptC] = useState('');
  const [optD, setOptD] = useState('');
  const [correctOpt, setCorrectOpt] = useState('A');
  const [qMarks, setQMarks] = useState(2);

  const fullSubject = subject || 'Grade 9 - IT';
  const subjectParts = fullSubject.split(' - ');
  const teachingGrade = subjectParts.length > 1 ? subjectParts[0] : 'Grade 9';
  const teachingSubject = subjectParts.length > 1 ? subjectParts[1] : fullSubject;

  const loadData = () => {
    axiosInstance.get('http://localhost:8081/api/quizzes').then(res => setQuizzes(res.data));
    axiosInstance.get('http://localhost:8081/api/question-bank').then(res => setQuestionBank(res.data));
  };

  useEffect(() => { loadData(); }, []);

  // 🟢 1. ටීචර් මුලින්ම ප්‍රශ්න බැංකුවට ප්‍රශ්න එකතු කිරීම හෝ Edit කිරීම
  const handleSaveQuestion = (e) => {
    e.preventDefault();
    const payload = {
      quiz_id: selectedQuizId || 1, // Default mapping if no quiz selected yet
      question_text: qText, marks: qMarks,
      option_a: optA, option_b: optB, option_c: optC, option_d: optD, correct_option: correctOpt
    };

    if (editingId) {
      // 📝 EDIT EXISTING QUESTION
      axiosInstance.put(`http://localhost:8081/api/edit-question/${editingId}`, payload).then(res => {
        if (res.data.status === "Success") {
          alert("✅ Question Updated in Bank!");
          setEditingId(null); clearForm(); loadData();
        }
      });
    } else {
      // ➕ ADD NEW QUESTION TO BANK
      axiosInstance.post('http://localhost:8081/api/add-question', payload).then(res => {
        if (res.data.status === "Success") {
          alert("✅ Question Saved to Bank!");
          clearForm(); loadData();
        }
      });
    }
  };

  // 🟢 2. ටීචර් ළමයාට දෙන්න අලුත් Quiz එකක් (Paper එකක්) සෑදීම
  const handleCreateQuizPaper = (e) => {
    e.preventDefault();
    const payload = { title: quizTitle, grade: teachingGrade, subject: teachingSubject, teacher_name: userName };
    axiosInstance.post('http://localhost:8081/api/add-quiz', payload).then(res => {
      if (res.data.status === "Success") {
        alert(`✅ Quiz Paper "${quizTitle}" Created! Now you can link questions.`);
        setQuizTitle(''); loadData();
      }
    });
  };

  // 🟢 3. ප්‍රශ්න බැංකුවේ තියෙන ප්‍රශ්නයක් අදාළ පේපර් එකට "Add" කිරීම හෝ වෙනස් කිරීම
  const handleAssignToQuiz = (question, quizId) => {
    if (!quizId) { alert("Please select a target Quiz Paper first!"); return; }
    
    const updatedPayload = {
      ...question,
      quiz_id: quizId
    };
    
    axiosInstance.put(`http://localhost:8081/api/edit-question/${question.id}`, updatedPayload).then(res => {
      loadData();
    });
  };

  const clearForm = () => {
    setQText(''); setOptA(''); setOptB(''); setOptC(''); setOptD(''); setCorrectOpt('A');
  };

  const handleStartEdit = (q) => {
    setEditingId(q.id); setQText(q.question_text);
    setOptA(q.option_a); setOptB(q.option_b); setOptC(q.option_c); setOptD(q.option_d);
    setCorrectOpt(q.correct_option); setQMarks(q.marks);
  };

  return (
    <div style={{ animation: 'fadeIn 0.5s', fontFamily: 'sans-serif' }}>
      <h2 style={{ color: '#1e293b', marginBottom: '20px' }}>⚙️ Advanced Question Bank & Quiz Assignment ({teachingSubject})</h2>
      
      {/* Top Creation Row */}
      <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '20px', marginBottom: '25px' }}>
        
        {/* Box A: Create Active Quiz Paper */}
        <div style={styles.card}>
          <h4 style={{ margin: '0 0 10px 0', color: '#15803d' }}>Step 1: Create Active Quiz Paper for Student</h4>
          <form onSubmit={handleCreateQuizPaper} style={{ display: 'flex', gap: '10px' }}>
            <input type="text" placeholder="e.g., Lesson 01 - Evaluation Quiz" value={quizTitle} onChange={e => setQuizTitle(e.target.value)} required style={styles.fullInput} />
            <button type="submit" style={{...styles.btn, backgroundColor: '#15803d'}}>Create Paper</button>
          </form>
        </div>

        {/* Box B: Target Selector */}
        <div style={styles.card}>
          <h4 style={{ margin: '0 0 10px 0', color: '#2563eb' }}>Step 2: Select Paper to Link/Add Questions</h4>
          <select value={selectedQuizId} onChange={e => setSelectedQuizId(e.target.value)} style={styles.fullInput}>
            <option value="">-- Choose Quiz Paper Destination --</option>
            {quizzes.filter(q => q.subject_name === teachingSubject).map(q => (
              <option key={q.id} value={q.id}>{q.title}</option>
            ))}
          </select>
        </div>
      </div>

      {/* Main Grid: Form and Bank View */}
      <div style={{ display: 'grid', gridTemplateColumns: '1fr 1.3fr', gap: '30px', alignItems: 'start' }}>
        
        {/* Left Side: Master Question Form */}
        <div style={styles.card}>
          <h3>{editingId ? "✏️ Edit Question Specs" : "➕ Create Master Question for Bank"}</h3>
          <form onSubmit={handleSaveQuestion} style={{ display: 'flex', flexDirection: 'column', gap: '12px', marginTop: '15px' }}>
            <div><label style={styles.label}>Question text</label><input type="text" value={qText} onChange={e => setQText(e.target.value)} required style={styles.fullInput} /></div>
            <div style={{ display: 'flex', gap: '10px' }}>
              <div style={styles.optRow}><input type="radio" checked={correctOpt === 'A'} onChange={() => setCorrectOpt('A')} /><input type="text" placeholder="Option A" value={optA} onChange={e => setOptA(e.target.value)} required style={styles.fullInput} /></div>
              <div style={styles.optRow}><input type="radio" checked={correctOpt === 'B'} onChange={() => setCorrectOpt('B')} /><input type="text" placeholder="Option B" value={optB} onChange={e => setOptB(e.target.value)} required style={styles.fullInput} /></div>
            </div>
            <div style={{ display: 'flex', gap: '10px' }}>
              <div style={styles.optRow}><input type="radio" checked={correctOpt === 'C'} onChange={() => setCorrectOpt('C')} /><input type="text" placeholder="Option C" value={optC} onChange={e => setOptC(e.target.value)} required style={styles.fullInput} /></div>
              <div style={styles.optRow}><input type="radio" checked={correctOpt === 'D'} onChange={() => setCorrectOpt('D')} /><input type="text" placeholder="Option D" value={optD} onChange={e => setOptD(e.target.value)} required style={styles.fullInput} /></div>
            </div>
            <button type="submit" style={{...styles.btn, backgroundColor: '#2563eb', padding: '12px'}}>{editingId ? "Update in Master Bank 💾" : "Save to Master Question Bank 📥"}</button>
            {editingId && <button type="button" onClick={() => { setEditingId(null); clearForm(); }} style={{background:'#cbd5e1', border:'none', padding:'8px', borderRadius:'6px', cursor:'pointer'}}>Cancel Edit</button>}
          </form>
        </div>

        {/* Right Side: Master Question Bank Manager List */}
        <div>
          <h3 style={{ marginBottom: '15px', color: '#1e293b' }}>📚 My Subject Question Bank Summary</h3>
          <div style={{ display: 'flex', flexDirection: 'column', gap: '15px' }}>
            {questionBank.map((q, index) => (
              <div key={q.id} style={{ backgroundColor: 'white', padding: '20px', borderRadius: '12px', border: '1px solid #e2e8f0', boxShadow: '0 2px 8px rgba(0,0,0,0.02)' }}>
                <div style={{ display: 'flex', justifyContent: 'space-between', fontSize: '12px', marginBottom: '8px' }}>
                  <span style={{ fontWeight: 'bold', color: '#475569' }}>Master Question #{index + 1}</span>
                  <span style={{ color: q.quiz_id && q.quiz_id !== 1 ? '#16a34a' : '#ef4444', fontWeight: 'bold' }}>
                    {q.quiz_id && q.quiz_id !== 1 ? "Linked to Active Paper" : "📌 Available in Bank"}
                  </span>
                </div>
                <h4 style={{ margin: '0 0 10px 0' }}>{q.question_text}</h4>
                
                {/* Actions Panel */}
                <div style={{ display: 'flex', gap: '10px', marginTop: '15px', borderTop: '1px solid #f1f5f9', paddingTop: '10px' }}>
                  <button onClick={() => handleStartEdit(q)} style={styles.miniBtn}>✏️ Edit Content</button>
                  <button 
                    onClick={() => handleAssignToQuiz(q, selectedQuizId)} 
                    disabled={!selectedQuizId}
                    style={{...styles.miniBtn, backgroundColor: selectedQuizId ? '#16a34a' : '#cbd5e1', color: 'white'}}
                  >
                    ➕ Add/Move to Selected Paper
                  </button>
                </div>
              </div>
            ))}
          </div>
        </div>

      </div>
    </div>
  );
}

const styles = {
  card: { backgroundColor: 'white', padding: '25px', borderRadius: '12px', boxShadow: '0 4px 12px rgba(0,0,0,0.02)', border: '1px solid #e2e8f0' },
  fullInput: { width: '100%', padding: '10px 12px', borderRadius: '8px', border: '1px solid #cbd5e1', outline: 'none', fontSize: '14px', boxSizing: 'border-box' },
  btn: { color: 'white', border: 'none', padding: '10px 20px', borderRadius: '8px', cursor: 'pointer', fontWeight: 'bold', fontSize: '13px', whiteSpace: 'nowrap' },
  label: { display: 'block', fontSize: '12px', fontWeight: 'bold', color: '#475569', marginBottom: '5px' },
  optRow: { display: 'flex', alignItems: 'center', gap: '8px', width: '100%' },
  miniBtn: { padding: '5px 12px', border: '1px solid #cbd5e1', backgroundColor: '#f8fafc', borderRadius: '6px', cursor: 'pointer', fontSize: '12px', fontWeight: 'bold', color: '#334155' }
};
